import {menuUsable,stepSelect,menuNeighbor} from '../shared/menu.js';
import {padAxis,padButton} from '../3d/gamepads.js';
/** Local menu/navigation adapter. Owns one input-only RAF, never gameplay/scores/audio. */
export function createControllerUI({root,hub,getContext,onPause,onBack,onHelp,onCenter,onLook,onStatus,onActivity,getLookDeadzone=()=>.18,getPads=()=>navigator.getGamepads?.()||[],document:doc=globalThis.document,request=globalThis.requestAnimationFrame,cancel=globalThis.cancelAnimationFrame,auto=true}={}){let disposed=false,frame=null,lastTime=0,nextMove=0,focused=null;
 const visible=menuUsable;
 function focus(n){focused?.classList.remove('lb-pad-focus');focused=n;n?.classList.add('lb-pad-focus');n?.focus({preventScroll:true});n?.scrollIntoView({block:'nearest'});}
 const adjustSelect=(n,step,wrap=false)=>stepSelect(n,step,{wrap});
 function move(surface,dx,dy){const all=[...surface.querySelectorAll('button,select,input[type="range"],input[type="checkbox"],a[href]')].filter(visible);if(!all.length)return;let active=all.includes(doc.activeElement)?doc.activeElement:all[0];if(!all.includes(doc.activeElement)){focus(active);return;}if(dx&&active.tagName==='SELECT'){adjustSelect(active,dx);return;}if(dx&&active.tagName==='INPUT'){if(active.type==='range'){dx>0?active.stepUp():active.stepDown();active.dispatchEvent(new Event('input',{bubbles:true}));active.dispatchEvent(new Event('change',{bubbles:true}));}else{active.checked=!active.checked;active.dispatchEvent(new Event('change',{bubbles:true}));}return;}
  const next=menuNeighbor(all,active,dx,dy);if(next)focus(next);}

 function confirm(surface){let n=doc.activeElement;if(!surface.contains(n)||!visible(n))n=[...surface.querySelectorAll('button,select,input')].find(visible);if(!n)return;focus(n);if(n.tagName==='SELECT'){adjustSelect(n,1,true);}else if(n.tagName==='INPUT'&&n.type==='checkbox'){n.checked=!n.checked;n.dispatchEvent(new Event('change',{bubbles:true}));}else{const selector=n.id?'#'+n.id:n.dataset.mode?'[data-mode="'+n.dataset.mode+'"]':n.dataset.players?'[data-players="'+n.dataset.players+'"]':null;n.click();if(selector){const next=root.querySelector(selector);if(next&&visible(next))focus(next);}}}
 function tick(now){if(disposed)return;const dt=Math.min(.05,Math.max(0,(now-lastTime)/1000||1/60));lastTime=now;let ctx=getContext(),pads=[];try{pads=getPads();}catch{}hub.poll(pads,ctx.key);const fresh=getContext();if(fresh.key!==ctx.key){hub.clear();ctx=fresh;}
  const status=hub.slots.map((s,i)=>s?'P'+(i+1)+' controller ready':null).filter(Boolean).join(' · ')||(hub.unsupported.length?'Controller mapping unsupported — use keyboard/touch.':'Pair an Xbox controller with Windows, then press a controller button.');onStatus?.(status);
  for(let player=0;player<hub.slots.length;player++){const pad=hub.pad(player);if(!pad)continue;if(ctx.mode==='game'&&(pad.axes.some((_,i)=>padAxis(pad,i,i>=2?getLookDeadzone():.18)!==0)||pad.buttons.some(b=>b.pressed||b.value>.4)))onActivity?.(player);if(hub.pressed(player,9)&&ctx.canPause){onPause();hub.clear();break;}if(ctx.mode==='game'){if(hub.pressed(player,8)){onHelp();hub.clear();break;}if(hub.pressed(player,4))onCenter(player);onLook(player,padAxis(pad,2,getLookDeadzone()),padAxis(pad,3,getLookDeadzone()),dt);continue;}if(ctx.mode!=='menu')continue;if(hub.pressed(player,1)){onBack();hub.clear();break;}if(hub.pressed(player,0)){confirm(ctx.surface||root);hub.clear();break;}
   const x=padButton(pad,14)?-1:padButton(pad,15)?1:Math.abs(padAxis(pad,0))>.55?Math.sign(padAxis(pad,0)):0,y=padButton(pad,12)?-1:padButton(pad,13)?1:Math.abs(padAxis(pad,1))>.55?Math.sign(padAxis(pad,1)):0;if((x||y)&&now>=nextMove){move(ctx.surface||root,Math.abs(padAxis(pad,0))>Math.abs(padAxis(pad,1))||x&&!y?x:0,y&&(!x||Math.abs(padAxis(pad,1))>=Math.abs(padAxis(pad,0)))?y:0);nextMove=now+240;}if(!x&&!y)nextMove=0;
  }
  if(auto)frame=request(tick);
 }
 if(auto)frame=request(tick);return{tick,dispose(){disposed=true;if(frame!==null)cancel(frame);focused?.classList.remove('lb-pad-focus');hub.dispose();}};
}
export function controllerGuide(){return `<p class="lb-eyebrow">XBOX CONTROLLER · BLUETOOTH OR USB</p><h2>Pick up and play.</h2><div class="lb-pad-diagram" role="img" aria-label="Xbox controls: left stick move; right stick look; A jump; X strike; B dodge; Y interact; RT pulse; RB run; LB recenter camera"><span>LT</span><span>LB · CENTER</span><b>LEFT STICK<br>MOVE</b><b>RIGHT STICK<br>LOOK</b><i class="pad-y">Y<br>INTERACT</i><i class="pad-x">X<br>STRIKE</i><i class="pad-b">B<br>DODGE</i><i class="pad-a">A<br>JUMP</i><span>RB · RUN</span><span>RT · PULSE</span></div><p><b>Menu button ☰:</b> pause / resume. <b>View button:</b> How to Play. Menus: D-pad or left stick to choose, left/right to adjust options, A to confirm and B to go back.</p><p>Windows: turn on the controller, hold Pair until its light flashes, then use <b>Settings → Bluetooth & devices → Add device</b>. Select your controller. Return to this browser and press a controller button. The first press detects it; release, then press A again to confirm a menu.</p><p>Two controllers join Player 1 and Player 2 in connection order. Mixed controller + keyboard/touch works too. Disconnecting a controller pauses an active adventure; reconnect, release the buttons, then intentionally resume. Non-standard mappings use the keyboard/touch fallback. In Settings, adjust camera speed/deadzone, invert look and choose Auto, Show or Hide for touch controls. Auto keeps controls available for mixed touch/controller co-op. The SHOW TOUCH toolbar button always restores them.</p><p class="lb-note">Bluetooth/USB must already work in Windows. Chrome or Edge on the HTTPS arcade link is preferred. The Xbox logo button is reserved by Windows and does not control this game. Physical Bluetooth behavior still depends on your PC/controller.</p><button id="lbGuideClose" class="lb-primary">GOT IT</button>`;}
